// Yale Bright Star Catalogue (BSC5, CDS V/50) runtime reader.
//
// Data generated by tools/fetch-stars.mjs: public/data/stars.bin contains full 9096 stars,
// src/astro/stars.generated.js contains named subset for HUD labels.
//
// Binary storage keeps initial bundle lightweight and enables on-demand loading
// alongside ephemerides and textures with content-hash cache busting.
// Optional visual enhancement; procedural fallback is active if binary fetch fails.
import { asset } from '../config.js';

/** Record structure: f32 raDeg, f32 decDeg, f32 vmag, f32 bv, f32 distLy */
export const STAR_RECORD_BYTES = 20;
const HEADER_BYTES = 12;
const MAGIC = 'SWST';

/**
 * Parse stars.bin binary buffer. Pure function, testable in Node.
 * @returns {{ count:number, ra:Float32Array, dec:Float32Array, mag:Float32Array,
 *             bv:Float32Array, distLy:Float32Array }|null}
 */
export function parseStarCatalog(buffer) {
  const dv = new DataView(buffer);
  if (buffer.byteLength < HEADER_BYTES) return null;
  if (String.fromCharCode(dv.getUint8(0), dv.getUint8(1), dv.getUint8(2), dv.getUint8(3)) !== MAGIC) return null;
  const version = dv.getUint16(4, true);
  if (version !== 1) return null; // Unsupported version
  const count = dv.getUint32(8, true);
  if (buffer.byteLength < HEADER_BYTES + count * STAR_RECORD_BYTES) return null;
  const ra = new Float32Array(count), dec = new Float32Array(count);
  const mag = new Float32Array(count), bv = new Float32Array(count);
  const distLy = new Float32Array(count);
  for (let i = 0; i < count; i++) {
    const o = HEADER_BYTES + i * STAR_RECORD_BYTES;
    ra[i] = dv.getFloat32(o, true);
    dec[i] = dv.getFloat32(o + 4, true);
    mag[i] = dv.getFloat32(o + 8, true);
    bv[i] = dv.getFloat32(o + 12, true);
    distLy[i] = dv.getFloat32(o + 16, true);
  }
  return { count, ra, dec, mag, bv, distLy };
}

let _cache = null;

/** Load star catalog; returns null on failure so caller can fall back to procedural starfield */
export async function loadStarCatalog() {
  if (_cache !== null) return _cache;
  try {
    const r = await fetch(asset('data/stars.bin'), { signal: AbortSignal.timeout(20000) });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    _cache = parseStarCatalog(await r.arrayBuffer());
    if (_cache) console.info(`[stars] Catalog loaded: ${_cache.count} stars`);
  } catch (e) {
    console.info('[stars] Star catalog unavailable, falling back to procedural starfield', e?.message ?? e);
    _cache = null;
  }
  return _cache;
}

/** B-V color index -> linear RGB via Ballesteros (2012) blackbody temperature approximation:
 *  T = 4600 * (1 / (0.92 * BV + 1.7) + 1 / (0.92 * BV + 0.62)) */
export function bvToRgb(bv, out = [1, 1, 1]) {
  const b = Math.max(-0.4, Math.min(2.0, bv));
  const T = 4600 * (1 / (0.92 * b + 1.7) + 1 / (0.92 * b + 0.62));
  // Color temperature -> RGB (Tanner Helland piecewise approximation, normalized to G=1)
  const t = T / 100;
  let r, g, bl;
  if (t <= 66) { r = 255; g = 99.4708025861 * Math.log(t) - 161.1195681661; }
  else { r = 329.698727446 * Math.pow(t - 60, -0.1332047592); g = 288.1221695283 * Math.pow(t - 60, -0.0755148492); }
  if (t >= 66) bl = 255;
  else if (t <= 19) bl = 0;
  else bl = 138.5177312231 * Math.log(t - 10) - 305.0447927307;
  const cl = (x) => Math.max(0, Math.min(255, x)) / 255;
  r = cl(r); g = cl(g); bl = cl(bl);
  // Normalize so max component is 1: magnitude governs brightness while color governs chromaticity,
  // preventing red stars from unintended brightness attenuation.
  const m = Math.max(r, g, bl) || 1;
  out[0] = r / m; out[1] = g / m; out[2] = bl / m;
  return out;
}

/** Magnitude -> relative flux. Pogson relation: 5 magnitudes = 100x flux ratio, 0 mag = 1.
 *  Physical quantity; compressed display intensity is computed separately via magToDisplayIntensity. */
export function magToIntensity(mag) {
  return Math.pow(10, -0.4 * mag);
}

/**
 * Magnitude -> display intensity.
 *
 * Pure Pogson flux is too extreme for 8-bit displays: 6th magnitude stars are 250x dimmer than 0 mag.
 * Power law compression (exponent 0.55) reflects human ocular Weber-Fechner logarithmic response,
 * retaining natural visual hierarchy:
 *
 * preserves contrast across stellar magnitudes without losing faint stars.
 * Perceptual gap between 6th and 1st magnitude is far smaller than 100x.
 * Compression maps physical flux to ocular perception.
 *
 * Exponent 0.55 maps 0 mag -> 1.0, 6.5 mag -> ~0.037 (clearly visible faint points),
 * Sirius (-1.46 mag) -> ~2.1x 0 mag.
 */
export function magToDisplayIntensity(mag) {
  return Math.pow(magToIntensity(mag), 0.55);
}
